import React from 'react';
import { Download, FileText, X } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { base44 } from '@/api/base44Client';

export default function ThinkingReportExport({ isOpen, onClose }) {
  if (!isOpen) return null;

  const handleExportAllReports = () => {
    console.log('Thinking Report Export: Starting export process');

    // Get all beliefs with reflections
    base44.entities.Thought.list().then(thoughts => {
      const thoughtsWithReflections = thoughts.filter(thought => 
        thought.ai_reflections && thought.ai_reflections.length > 0
      );

      if (thoughtsWithReflections.length === 0) {
        alert('No thinking reports found to export.');
        return;
      }

      // Generate comprehensive report
      let reportContent = `Trace Thinking Reports Export
Generated: ${new Date().toLocaleString()}

=== ALL THINKING REPORTS ===

`;

      thoughtsWithReflections.forEach((thought, index) => {
        reportContent += `
${index + 1}. Belief: "${thought.statement}"
Confidence: ${thought.confidence}/10
Created: ${new Date(thought.created_date).toLocaleDateString()}

`;

        thought.ai_reflections.forEach((reflection, refIndex) => {
          const content = JSON.parse(reflection.content);
          reportContent += `
   Reflection ${refIndex + 1} (${new Date(reflection.date).toLocaleDateString()}):
   ${content.summary || 'No summary available'}

`;

          if (content.clarifying_questions && content.clarifying_questions.length > 0) {
            reportContent += `   Questions:
`;
            content.clarifying_questions.forEach((question, qIndex) => {
              reportContent += `     ${qIndex + 1}. ${question}\n`;
            });
          }

          if (content.assumptions_noticed) {
            reportContent += `   Assumptions: ${content.assumptions_noticed}\n`;
          }

          reportContent += '\n';
        });

        reportContent += '\n---\n';
      });

      // Create and download file
      const blob = new Blob([reportContent], { type: 'text/plain' });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = `trace-thinking-reports-${new Date().toISOString().split('T')[0]}.txt`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      URL.revokeObjectURL(url);

      onClose();
      console.log('Thinking Report Export: Export completed');
    });
  };

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
      <div className="bg-white rounded-xl p-6 max-w-2xl w-full mx-4 max-h-[80vh] overflow-y-auto">
        <div className="flex items-center justify-between mb-4">
          <h3 className="text-xl font-semibold text-[#5C6B5E]">Export All Thinking Reports</h3>
          <Button
            onClick={onClose}
            variant="ghost"
            size="sm"
            className="text-slate-400 hover:text-slate-600"
          >
            <X className="h-4 w-4" />
          </Button>
        </div>

        <div className="space-y-4">
          <p className="text-sm text-slate-600 mb-4">
            Export all your thinking reports as a single text file. This will include all beliefs that have AI reflections.
          </p>

          <div className="flex gap-3">
            <Button
              onClick={handleExportAllReports}
              className="flex-1 bg-[#5C6B5E] hover:bg-[#4a574c] text-white"
            >
              <Download className="w-4 h-4 mr-2" />
              Download All Reports
            </Button>
            <Button
              onClick={onClose}
              variant="outline"
              className="flex-1 border-slate-200 text-slate-600"
            >
              Cancel
            </Button>
          </div>
        </div>
      </div>
    </div>
  );
}
